    private static bool NonDecreasing(IReadOnlyList<double> values){for(var index=1;index<values.Count;index++)if(values[index]<values[index-1])return false;return true;}
    private static List<Point2D> RemoveAdjacentDuplicates(IEnumerable<Point2D> source){var result=new List<Point2D>();foreach(var point in source)if(result.Count==0||result[^1].DistanceTo(point)>GeometryTolerancePolicy.DefaultEndpointEqualityMm)result.Add(point);return result;}
    private static double MaximumScale(Matrix2D transform)=>Math.Max(Math.Sqrt(transform.M11*transform.M11+transform.M12*transform.M12),Math.Sqrt(transform.M21*transform.M21+transform.M22*transform.M22));
    private static bool HasNonZeroZ(object source)
    {
        foreach(var name in new[]{"P1","P2","Start","End","Center","Location","InsertionPoint","MajorAxis"})if(Math.Abs(Number(Get(Get(source,name),"Z")))>1e-9)return true;foreach(var collectionName in new[]{"Vertices","ControlPoints","FitPoints"})if(Get(source,collectionName) is IEnumerable values)foreach(var value in values){var point=Get(value,"Point")??Get(value,"Location")??value;if(Math.Abs(Number(Get(point,"Z")))>1e-9)return true;}return false;
